 if(p&&!s)return eventItemForm(p);
 modal(p?'Edit product':'Add product',`<form class="event-product-editor">${input('name','Product name',initial.name??p?.name??'','text','required maxlength="160"')}${input('price','Event price · PHP',initial.price??(p?amount(p.price_cents):''),'number','required min="0" step="0.01"')}${select('product_type','Flavors',[['simple','No flavors'],['flavors','Add flavors / options']],'simple')}${stockStepper('available','Available stock',initial.available??s?.remaining??0)}<p class="muted">Each sale deducts one unit. Stock is separate for this event.</p><label class="check"><input name="active" type="checkbox" ${(initial.active??p?.active??true)?'checked':''}>Available for sale</label><button type="submit" class="primary">Save product</button></form>`,async f=>{
  await api('pos_save_event_simple_item',{event_id:eventId,id:pid,stock_id:sid,revision:p?.revision||0,stock_revision:s?.revision||0,expected_available:s?.remaining||0,available:Number(f.get('available')),name:f.get('name'),price_cents:cents(f.get('price')),active:f.has('active')});
  await load();dialog.close();render();status('Saved product, price and stock.');
 });const form=dialog.querySelector('form');bindStockQuantities(form);
 form.elements.product_type.onchange=()=>{const f=new FormData(form);dialog.close();variantItemForm(p,{name:f.get('name'),price:f.get('price'),active:f.has('active'),available:f.get('available')});};
