async function loadReport(){report=eventId?await api('pos_event_report',{event_id:eventId,date:reportDate}):null;}
function renderReport(){if(!event)return '<p class="notice">Choose an event first.</p>';if(!report)return '<p>Loading report…</p>';const total=report.sales.reduce((s,x)=>s+Number(x.total_cents),0),count=report.sales.reduce((s,x)=>s+Number(x.orders),0),c=report.cash;
 return `<div class="section-head">${accountingDatePicker('report_date','Report day',reportDate,today(),{attrs:'id="report-date"'})}${button('refresh-report','Refresh report')}</div><div class="metrics"><div class="metric">Sales including delivery<strong>${money(total)}</strong></div><div class="metric">Paid orders<strong>${count}</strong></div><div class="metric">Expected cash in drawer<strong>${c?money(c.expected_cents):'Not opened'}</strong></div></div><section class="panel"><h2>Sales by payment method</h2><p class="muted">Cancelled and refunded orders are excluded. Sales are already included in Accounting.</p><div class="table-wrap"><table><thead><tr><th>Method</th><th>Orders</th><th class="num">Sales</th><th class="num">Delivery included</th></tr></thead><tbody>${report.sales.map(s=>`<tr><td>${esc(s.method)}</td><td>${s.orders}</td><td class="num">${money(s.total_cents)}</td><td class="num">${money(s.delivery_cents)}</td></tr>`).join('')||'<tr><td colspan="4">No sales for this day.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="section-head"><h2>Cash reconciliation</h2><div class="row">${c&&!c.closed_at?button('cash-movement','Record cash in / out')+button('close-cash','Count & close'):c?.closed_at&&role==='owner'?button('reopen-cash','Reopen session'):!c&&reportDate===today()?button('open-cash','Open cash session'):''}</div></div><p class="muted">Expected cash = opening float + cash payments received + cash in − cash out. Cancellations and refund labels do not mean money has left the drawer: record an actual cash refund as cash out. Cash movements do not create extra accounting entries.</p>${c?`<div class="totals"><div><span>Opening float</span><strong>${money(c.opening_cents)}</strong></div><div><span>Expected cash</span><strong>${money(c.expected_cents)}</strong></div>${c.closed_at?`<div><span>Counted cash</span><strong>${money(c.counted_cents)}</strong></div><div class="grand"><span>Over / short at close</span><strong>${money(c.counted_cents-c.expected_at_close)}</strong></div>`:''}</div>`:'<p>No cash session for this date.</p>'}${report.movements.length?`<div class="table-wrap"><table><thead><tr><th>Cash movement</th><th class="num">Amount</th></tr></thead><tbody>${report.movements.map(m=>`<tr><td>${esc(m.reason)}</td><td class="num">${money(m.amount_cents)}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section class="panel"><h2>Remaining event stock</h2><p class="muted">Current stock across the whole event.</p><div class="table-wrap"><table><thead><tr><th>Stock item</th><th class="num">Remaining</th></tr></thead><tbody>${report.stock.map(s=>`<tr><td>${esc(s.name)}</td><td class="num">${s.remaining}</td></tr>`).join('')}</tbody></table></div></section>`;
}
